SCORE_STATUSES: Final[FrozenSet[str]] = frozenset(
    {
        SCORE_STATUS_ACCEPTED,
        SCORE_STATUS_REJECTED,
        SCORE_STATUS_SKIPPED,
        SCORE_STATUS_DUPLICATE,
        SCORE_STATUS_INVALID,
        SCORE_STATUS_UNKNOWN,
    }
)


